254	    @Override
255	    @Transactional
256	    public void createOwner(Owner owner) throws DataAccessException {
257	        rejectWhenDailyLimitReached(owner);
258	        rejectWhenCityAtCapacity(owner);
259	        rejectWhenDuplicateIdentity(owner);
260	        owner.setHouseholdId(deriveHouseholdId(owner));
261	        List<Owner> householdMembers = findHouseholdMembers(owner);
262	        assignPossibleDuplicate(owner);
263	        owner.setHouseholdMemberCount(householdMembers.size() + 1);
264	        owner.setMembershipLevelCap(membershipLevelCap(householdMembers));
265	        if (owner.getCustomerCode() == null) {
266	            owner.setCustomerCode(deduplicateCustomerCode(deriveCustomerCode(owner)));
267	        }
268	        if (owner.getNamesakeCount() == null) {
269	            owner.setNamesakeCount(countNamesakes(owner));
270	        }
271	        owner.setBulkSignupWarning(exceedsBulkSignupThreshold(owner));
272	        ownerRepository.save(owner);
273	    }
274	
275	    /** Number of owners created on a single day beyond which the bulk-signup warning is raised. */
276	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
277	
278	    /**
279	     * Whether more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created
280	     * today (compared by {@code registrationDate}), evaluated before this owner is persisted so it
281	     * reflects the owners present at creation time. The new owner's registration date, defaulted to
282	     * today by the controller, determines which day is counted — the same accumulation path as the
283	     * daily-limit rule.
284	     */
285	    private boolean exceedsBulkSignupThreshold(Owner owner) {
286	        LocalDate day = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
287	        return countOwnersRegisteredOn(day) > BULK_SIGNUP_WARNING_THRESHOLD;
288	    }
289	
290	    /**
291	     * Count the existing owners that already share this owner's first name and last name,
292	     * compared case-insensitively (with surrounding/collapsed whitespace ignored). Evaluated
293	     * before the owner is persisted, so it reflects the owners present at creation time.
294	     */
295	    private int countNamesakes(Owner owner) {
296	        String firstName = IdentityNormalizer.normalize(owner.getFirstName());
297	        String lastName = IdentityNormalizer.normalize(owner.getLastName());
298	        return (int) findActiveOwners().stream()
299	            .filter(existing -> firstName.equals(IdentityNormalizer.normalize(existing.getFirstName()))
300	                && lastName.equals(IdentityNormalizer.normalize(existing.getLastName())))
301	            .count();
302	    }
303	
304	    /**
305	     * The existing owners that have not been soft-deleted. Duplicate and identity checks run
306	     * against this set, so an owner flagged {@code deleted} (see {@link #deleteOwner(Owner)}) is
307	     * ignored and no longer blocks a create that would otherwise match it.
308	     */
309	    private List<Owner> findActiveOwners() {
310	        return ownerRepository.findAll().stream()
311	            .filter(existing -> !existing.isDeleted())
312	            .toList();
313	    }
314	
315	    /**
316	     * The existing owners that already belong to this owner's household, i.e. those carrying the
317	     * same deterministic {@code householdId} (see {@link #deriveHouseholdId(Owner)}). Because the
318	     * household id is derived purely from the normalized last name and postcode, this is exactly
319	     * the set of owners sharing that last name and postcode. Evaluated before the owner is
320	     * persisted, so it reflects the owners present at creation time. The owner's own
321	     * {@code householdId} must already be assigned before calling.
322	     */
323	    private List<Owner> findHouseholdMembers(Owner owner) {
324	        String householdId = owner.getHouseholdId();
325	        return findActiveOwners().stream()
326	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
327	            .toList();
328	    }
329	
330	    /**
331	     * Derive the owner's deterministic household identifier: the first twelve hexadecimal characters
332	     * of the SHA-256 digest over {@code normalizedLastName + '|' + postcode}. Two owners with the
333	     * same last name (compared case-insensitively with collapsed whitespace) and postcode therefore
334	     * map to the same value automatically, without any opt-in, so they form one household.
335	     */
336	    private static String deriveHouseholdId(Owner owner) {
337	        String lastName = IdentityNormalizer.normalize(owner.getLastName());
338	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
339	        return sha256HexPrefix(lastName + "|" + postcode, 12);
340	    }
341	
342	    /**
343	     * The membership-level ceiling for a new owner joining {@code householdMembers}: one above the
344	     * maximum membership level among the existing members. Returns {@code null} when the household
345	     * has no existing member, so no cap applies. Evaluated before the owner is persisted, so it
346	     * reflects the members (and their levels) present at creation time.
347	     */
348	    private Integer membershipLevelCap(List<Owner> householdMembers) {
349	        return householdMembers.stream()
350	            .map(MembershipLevels::level)
351	            .max(Integer::compareTo)
352	            .map(max -> max + 1)
353	            .orElse(null);
354	    }
355	
356	    /**
357	     * Reject the create with a {@code 409 Conflict} when the owner's derived {@code identityKey}
358	     * (see {@link IdentityKeyNormalizer}) exactly matches that of an existing, non-deleted owner.
359	     * This single key is the whole of duplicate detection: the former separate household-duplicate
360	     * block from the computed {@code householdId} no longer applies. Owners flagged {@code deleted}
361	     * are ignored (see {@link #findActiveOwners()}); the e-mail-domain blocklist is applied earlier,
362	     * before this method runs. Evaluated before the owner is persisted, so it reflects the owners
363	     * present at creation time.
364	     */
365	    private void rejectWhenDuplicateIdentity(Owner owner) {
366	        String identityKey = IdentityKeyNormalizer.derive(owner);
367	        boolean duplicate = findActiveOwners().stream()
368	            .anyMatch(existing -> identityKey.equals(IdentityKeyNormalizer.derive(existing)));
369	        if (duplicate) {
370	            throw new DuplicateIdentityException(
371	                "an owner with the same identity key already exists");
372	        }
373	    }
374	
375	    /**
376	     * Set the new owner's soft-duplicate flags. Because the telephone is part of the
377	     * {@code identityKey}, two owners sharing a last name and postcode but with different telephones
378	     * are no longer a hard duplicate; they are surfaced as a soft match instead. The flag is raised
379	     * when the owner's {@code identityKey} differs from an existing, non-deleted owner's yet their
380	     * last-name {@link Soundex} codes and postcodes match, pointing {@code possibleDuplicateOf} at
381	     * that owner; otherwise both flags are cleared so the field is always present in the response.
382	     * Evaluated before the owner is persisted, so it reflects the owners present at creation time.
383	     */
384	    private void assignPossibleDuplicate(Owner owner) {
385	        String identityKey = IdentityKeyNormalizer.derive(owner);
386	        String soundex = Soundex.encode(owner.getLastName());
387	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
388	        Owner match = findActiveOwners().stream()
389	            .filter(existing -> !identityKey.equals(IdentityKeyNormalizer.derive(existing)))
390	            .filter(existing -> soundex.equals(Soundex.encode(existing.getLastName())))
391	            .filter(existing -> postcode.equals(existing.getPostcode() == null ? "" : existing.getPostcode()))
392	            .findFirst()
393	            .orElse(null);
394	        if (match != null) {
395	            owner.setPossibleDuplicate(true);
396	            owner.setPossibleDuplicateOf(match.getId());
397	        }
398	        else {
399	            owner.setPossibleDuplicate(false);
400	            owner.setPossibleDuplicateOf(null);
401	        }
402	    }
403	
404	    /** Maximum number of owners that may be created on any single day (by registration date). */
405	    private static final long DAILY_OWNER_LIMIT = 100L;
406	
407	    /**
408	     * Reject the create when {@value #DAILY_OWNER_LIMIT} or more owners have already been created
409	     * today (compared by {@code registrationDate}). Evaluated before the owner is persisted, so it
410	     * reflects the owners present at creation time. The new owner's own registration date, defaulted
411	     * to today by the controller, determines which day the limit is checked against.
412	     */
413	    private void rejectWhenDailyLimitReached(Owner owner) {
414	        LocalDate day = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
415	        if (countOwnersRegisteredOn(day) >= DAILY_OWNER_LIMIT) {
416	            throw new DailyOwnerLimitExceededException(
417	                DAILY_OWNER_LIMIT + " or more owners have already been created on " + day);
418	        }
419	    }
420	
421	    /**
422	     * Count the existing owners whose {@code registrationDate} equals the given day. Evaluated
423	     * before the owner is persisted, so it reflects the owners present at creation time.
424	     */
425	    private long countOwnersRegisteredOn(LocalDate day) {
426	        return ownerRepository.findAll().stream()
427	            .filter(existing -> day.equals(existing.getRegistrationDate()))
428	            .count();
429	    }
430	
431	    /** Maximum number of owners allowed to live in any single city. */
432	    private static final long CITY_CAPACITY = 50L;
433	
434	    /**
435	     * Reject the create when the owner's city already contains {@value #CITY_CAPACITY} or more
436	     * owners (compared case-insensitively with collapsed whitespace). Evaluated before the owner
437	     * is persisted, so it reflects the owners present at creation time.
438	     */
439	    private void rejectWhenCityAtCapacity(Owner owner) {
440	        if (countOwnersInCity(owner) >= CITY_CAPACITY) {
441	            throw new CityCapacityExceededException(
442	                "city " + owner.getCity() + " already contains " + CITY_CAPACITY + " or more owners");
443	        }
444	    }
445	
446	    /**
447	     * Count the existing owners that already live in this owner's city, compared
448	     * case-insensitively (with surrounding/collapsed whitespace ignored). Evaluated before the
449	     * owner is persisted, so it reflects the owners present at creation time.
450	     */
451	    private long countOwnersInCity(Owner owner) {
452	        String city = IdentityNormalizer.normalize(owner.getCity());
453	        return ownerRepository.findAll().stream()
454	            .filter(existing -> city.equals(IdentityNormalizer.normalize(existing.getCity())))
455	            .count();
456	    }
457	
458	    /** Region-to-inclusive 4-digit postcode range {@code {low, high}}. */
459	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
460	        "NSW", new int[] {2000, 2099},
461	        "VIC", new int[] {3000, 3099},
462	        "QLD", new int[] {4000, 4099});
463	
464	    /** Region code used when the postcode maps to no known region (or is absent). */
465	    private static final String UNKNOWN_REGION = "UNKNOWN";
466	
467	    /**
468	     * Builds the customer code {@code '<REGION>-<HASH8>'}: the region code derived from the
469	     * owner's postcode, a hyphen, and the first eight upper-case hexadecimal characters of the
470	     * SHA-256 digest over the owner's normalized (E.164) telephone concatenated with the last
471	     * name. No sequence number is used; the identity is fully derived from the region and hash.
472	     */
473	    private String deriveCustomerCode(Owner owner) {
474	        String region = regionForPostcode(owner.getPostcode());
475	        String telephone = TelephoneNormalizer.toComparable(owner.getTelephone());
476	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
477	        return region + "-" + sha256Hex8(telephone + lastName);
478	    }
479	
480	    /**
481	     * De-duplicates a computed {@code customerCode} against the existing owners: if no owner already
482	     * carries {@code baseCode} it is returned unchanged, otherwise {@code '-<n>'} is appended with the
483	     * smallest {@code n} of 2 or more that yields a value no existing owner holds. Evaluated before the
484	     * owner is persisted, so it reflects the owners present at creation time.
485	     */
486	    private String deduplicateCustomerCode(String baseCode) {
487	        Set<String> existingCodes = findActiveOwners().stream()
488	            .map(Owner::getCustomerCode)
489	            .filter(Objects::nonNull)
490	            .collect(Collectors.toSet());
491	        if (!existingCodes.contains(baseCode)) {
492	            return baseCode;
493	        }
494	        int n = 2;
495	        while (existingCodes.contains(baseCode + "-" + n)) {
496	            n++;
497	        }
498	        return baseCode + "-" + n;
499	    }
500	
501	    /**
502	     * Returns the region code whose inclusive postcode range contains {@code postcode}
503	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), or
504	     * {@code "UNKNOWN"} when the postcode is absent, not a 4-digit value, or in no known range.
505	     */
506	    private static String regionForPostcode(String postcode) {
507	        if (postcode == null || !postcode.matches("\\d{4}")) {
508	            return UNKNOWN_REGION;
509	        }
510	        int value = Integer.parseInt(postcode);
511	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
512	            int[] range = entry.getValue();
513	            if (value >= range[0] && value <= range[1]) {
514	                return entry.getKey();
515	            }
516	        }
517	        return UNKNOWN_REGION;
518	    }
519	
520	    /**
521	     * Returns the first eight upper-case hexadecimal characters (the first four bytes) of the
522	     * SHA-256 digest of the UTF-8 bytes of {@code value}.
523	     */
524	    private static String sha256Hex8(String value) {
525	        return sha256HexPrefix(value, 8).toUpperCase();
526	    }
527	
528	    /**
529	     * Returns the first {@code hexChars} lower-case hexadecimal characters of the SHA-256 digest of
530	     * the UTF-8 bytes of {@code value}.
531	     */
532	    private static String sha256HexPrefix(String value, int hexChars) {
533	        try {
534	            byte[] digest = MessageDigest.getInstance("SHA-256")
535	                .digest(value.getBytes(StandardCharsets.UTF_8));
536	            StringBuilder sb = new StringBuilder(hexChars);
537	            for (int i = 0; sb.length() < hexChars; i++) {
538	                sb.append(String.format("%02x", digest[i]));
539	            }
540	            return sb.substring(0, hexChars);
541	        }
542	        catch (NoSuchAlgorithmException e) {
543	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
544	        }
545	    }
546	
