565	    private <T> T findEntityById(Supplier<T> supplier) {
566	        try {
567	            return supplier.get();
568	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
569	            // Just ignore not found exceptions for Jdbc/Jpa realization
570	            return null;
571	        }
572	    }
